"""
B2.5/B2.6/B2.7/B2.8 build of the grasp reachability maps: both arms, all 12 approach bins, collision filter on (design plan 3.1).

    source .venv/bin/activate
    MUJOCO_GL=egl python experiments/reach_map_build.py [--out data/reach_map] [--sides left right] [--bins 0 1 ...] [--quick-samples N] [--validation-samples N]

Per arm: one quick random sample of joint vectors (every level pose of any bin) gives the convex outer bound and the spread-out seeds of each bin; per bin the IK flood fill (collision
filter on: the arm against itself, the other arm at home, the torso, the pedestal at its lowest, the base with the battery and the neck at its drive pose) fills 5 mm voxels; enclosed
pockets at most hole_fill_max_m wide are then filled without any IK test (David 2026-10-19), larger ones stay as real holes; the 1 cm cubes need all 8 of their voxels. A file per
(arm, bin) is written (temporary file, checked, renamed) as OUT/<side>_bin<k>.npz; a file whose staleness hash (robot model, settings, sampler version) matches is skipped, so an
interrupted build resumes. Validation per map: random level poses of the bin that are collision-free (a different random sample than the build's) must land in reached voxels; the
share that lands in a reachable cube is lower by design (the cube rule drops edge cubes). Build times and the validation go to OUT/build_summary.json (written after every map).
"""

import argparse
import hashlib
import json
import math
import os
import resource
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402
from scipy.spatial import ConvexHull  # noqa: E402

from src.arm_collision import ArmCollisionChecker  # noqa: E402
from src.arm_kinematics import arm_chain, batch_fk, shoulder_origin  # noqa: E402
from src.grasp_rules import bin_center, joint_bounds  # noqa: E402
from src.gripper_geometry import grasp_cfg  # noqa: E402
from src.reach_map import (Grid, cubes_from_voxels, fill_small_pockets, flood_fill, inside_bound, load_map, outer_bound, quick_sample, save_map)  # noqa: E402
from src.task_beaker_hotplate import home_targets, load_task  # noqa: E402
from src.task_config import STAGING_CFG, TASK_CFG  # noqa: E402
from reach_map_pilot import farthest_points  # noqa: E402

T0 = time.time()


def log(*a):
    print(f"[{time.time() - T0:7.0f} s, {resource.getrusage(resource.RUSAGE_SELF).ru_maxrss // 1024} MB]", *a, flush=True)


def stamp_of(model, C):
    """The staleness hash: the robot's model arrays (the bodies and geoms of the robot, not the scene), the settings and the sampler version."""
    h = hashlib.sha1()
    root = model.body("base_link").id
    def under(b):
        while b > 0:
            if b == root:
                return True
            b = int(model.body_parentid[b])
        return False
    bodies = [b for b in range(model.nbody) if under(b)]
    geoms = [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) in bodies]
    for arr, rows in ((model.body_pos, bodies), (model.body_quat, bodies), (model.geom_pos, geoms), (model.geom_quat, geoms), (model.geom_size, geoms), (model.geom_type, geoms),
                      (model.geom_contype, geoms), (model.geom_conaffinity, geoms), (model.jnt_range, range(model.njnt)), (model.jnt_axis, range(model.njnt))):
        h.update(np.ascontiguousarray(np.round(arr[list(rows)].astype(float), 6)).tobytes())
    h.update(json.dumps(C, sort_keys=True, default=str).encode())
    return h.hexdigest()[:16]


def main(args):
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    sim = load_task(cameras=False)
    m = sim.model
    summ_path = out / "build_summary.json"
    summary = json.loads(summ_path.read_text()) if summ_path.exists() else {}
    for side in args.sides:
        C = grasp_cfg(m, side)
        if args.quick_samples:
            C = {**C, "quick_samples": args.quick_samples}
        stamp_cfg = {k: v for k, v in C.items() if k != "quick_samples"}
        stamp = stamp_of(m, stamp_cfg)
        todo = []
        for k in args.bins:
            f = out / f"{side}_bin{k}.npz"
            if f.exists():
                try:
                    load_map(f, stamp)
                    log(f"{side} bin {k}: map file is current, skipped")
                    continue
                except Exception as e:
                    log(f"{side} bin {k}: existing file unusable ({e}), rebuilt")
            todo.append(k)
        if not todo:
            continue
        chain = arm_chain(m, side)
        sh = shoulder_origin(chain)
        lo, hi = joint_bounds(m, side, C)
        pad = np.array(C["pad_center_in_tcp"])
        other = "right" if side == "left" else "left"
        checker = ArmCollisionChecker(m, side, home_targets(m, TASK_CFG)[other], finger_open=STAGING_CFG["finger_open"])
        log(f"=== {side} arm: stamp {stamp}, {len(todo)} bins to build {todo}; collision filter: {int(checker.moving.sum())} moving geoms against {int((checker.active & ~checker.moving).sum())} static, margin {checker.margin} m")
        t = time.time()
        P, Q, K, drawn = quick_sample(chain, lo, hi, C["quick_samples"], None, C, C["seed"])
        P = P - sh
        log(f"quick sample: {drawn:,} joint vectors in {time.time() - t:.0f} s -> {len(P):,} level poses of any bin")
        t = time.time()
        Pv, Qv, Kv, drawn_v = quick_sample(chain, lo, hi, args.validation_samples, None, C, C["seed"] + 1)
        Pv = Pv - sh
        coll = checker.check(Qv)
        Pv, Qv, Kv = Pv[~coll], Qv[~coll], Kv[~coll]
        log(f"validation sample: {drawn_v:,} joint vectors -> {len(coll):,} level poses, {int(coll.sum()):,} collide and are left out, {len(Pv):,} kept ({time.time() - t:.0f} s)")
        home_q = home_targets(m, TASK_CFG)[side]
        for k in todo:
            tk = time.time()
            Pk, Qk = P[K == k], Q[K == k]
            if len(Pk) < 100:
                log(f"{side} bin {k}: only {len(Pk)} level poses in the quick sample, bin skipped")
                continue
            eq = outer_bound(Pk)
            g = Grid(Pk.min(axis=0) - C["hull_margin"] - C["grid_margin"], Pk.max(axis=0) + C["hull_margin"] + C["grid_margin"], C)
            sel = farthest_points(Pk, C["n_seeds"], 0)
            p_home, _ = batch_fk(chain, home_q[None], pad)
            s_idx, s_in = g.index_of(np.vstack([Pk[sel], (p_home[0] - sh)[None]]))
            s_Q = np.vstack([Qk[sel], home_q[None]])
            s_idx, s_Q = s_idx[s_in], s_Q[s_in]
            # the seeds must be collision-free to start from (a colliding seed pose would only be rejected, its voxel retried)
            log(f"--- {side} bin {k} (centre {math.degrees(bin_center(k, C)):.0f} deg): {len(Pk):,} level poses in the sample, hull volume {ConvexHull(Pk).volume:.3f} m^3, grid {g.shape} = {np.prod(g.shape) / 1e6:.1f} M voxels, {len(s_idx)} seeds")
            res = flood_fill(chain, lo, hi, g, eq, sh, s_idx, s_Q, k, C, C["seed"], log=log, collision=checker)
            state, fst = res["state"], res["stats"]
            reached0 = state == 1
            reached, hs = fill_small_pockets(reached0, max(1, int(round(C["hole_fill_max_m"] / C["voxel"]))))
            cubes = cubes_from_voxels(reached)
            # validation: collision-free random level poses of this bin must land in reached voxels
            sel_v = Kv == k
            vidx, vin = g.index_of(Pv[sel_v])
            vox_ok = np.zeros(int(sel_v.sum()), bool)
            vox_ok[vin] = reached[tuple(vidx[vin].T)]
            cube_ok = np.zeros(len(vox_ok), bool)
            cube_ok[vin] = cubes[tuple((vidx[vin] // 2).T)]
            nv = max(len(vox_ok), 1)
            info = {"side": side, "bin": k, "seconds": time.time() - tk, "flood_seconds": res["seconds"], "waves": res["waves"], "ik_calls": fst["ik_calls"], "collision_checks": fst["checks"],
                    "check_seconds": fst["check_seconds"], "first_collisions": fst["first_collisions"], "rescued": fst["rescued"], "lost_to_collision": fst["lost_to_collision"],
                    "voxels_reached": int(reached0.sum()), "voxels_failed": int((state == 2).sum()), "voxels_after_fill": int(reached.sum()), "pockets": hs, "cubes": int(cubes.sum()),
                    "cube_volume_m3": float(cubes.sum() * C["cube"] ** 3), "validation_poses": int(len(vox_ok)), "validation_in_voxel": int(vox_ok.sum()), "validation_in_cube": int(cube_ok.sum()),
                    "validation_voxel_pct": 100 * vox_ok.sum() / nv, "validation_cube_pct": 100 * cube_ok.sum() / nv, "peak_mb": resource.getrusage(resource.RUSAGE_SELF).ru_maxrss // 1024}
            save_map(out / f"{side}_bin{k}.npz", reached, g, side, k, stamp, info)
            summary[f"{side}_bin{k}"] = info
            tmp = Path(str(summ_path) + ".tmp")
            tmp.write_text(json.dumps(summary, indent=1))
            json.loads(tmp.read_text())
            os.replace(tmp, summ_path)
            log(f"{side} bin {k} DONE in {info['seconds']:.0f} s: {info['voxels_reached']:,} voxels reached, {info['voxels_failed']:,} failed; pockets {hs['pockets']} (filled {hs['filled_pockets']} = {hs['filled_voxels']} voxels, "
                f"kept {hs['kept_pockets']} = {hs['kept_voxels']} voxels, largest {hs['kept_largest']} voxels across); {info['cubes']:,} cubes = {info['cube_volume_m3']:.3f} m^3; "
                f"collision checks {fst['checks']:,} in {fst['check_seconds']:.0f} s, {fst['first_collisions']:,} first solutions collided, {fst['rescued']:,} rescued, {fst['lost_to_collision']:,} lost; "
                f"validation {len(vox_ok):,} poses: {info['validation_voxel_pct']:.2f} % in a reached voxel, {info['validation_cube_pct']:.2f} % in a reachable cube")
            del res, state, reached, reached0, cubes
        del checker
    done = [v for v in summary.values()]
    log(f"ALL DONE: {len(done)} maps, total flood fill {sum(v['flood_seconds'] for v in done) / 60:.1f} min, total {sum(v['seconds'] for v in done) / 60:.1f} min, "
        f"validation {sum(v['validation_in_voxel'] for v in done):,} of {sum(v['validation_poses'] for v in done):,} poses in reached voxels")


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "reach_map"))
    ap.add_argument("--sides", nargs="*", default=["left", "right"])
    ap.add_argument("--bins", nargs="*", type=int, default=list(range(12)))
    ap.add_argument("--quick-samples", type=int, default=None, help="override GRASP_MAP_CFG quick_samples (smoke tests)")
    ap.add_argument("--validation-samples", type=int, default=20_000_000)
    main(ap.parse_args())
